types.source:
interface TooltipItem {
  name: string;
  role?: string;
}

interface HoverCardItem {
  /** Card heading */
  title: string;
  /** One or two sentences under the title */
  description: string;
  /** Link target; the whole card is the link */
  href: string;
  /** Optional leading icon, e.g. a lucide-react element */
  icon?: React.ReactNode;
}

interface FileNode {
  name: string;
  /** Presence of `children` makes the node a folder */
  children?: FileNode[];
  /** Folders start open unless this is false */
  defaultOpen?: boolean;
}

interface FocusCard {
  /** Shown over the card while it has the focus; always read by screen readers */
  title: string;
  /** Image URL */
  src: string;
  /** Describes the photo; leave empty when the title says enough */
  alt?: string;
  /** Makes the card a link */
  href?: string;
}

interface LayoutGridItem {
  /** Tile title — the tile's accessible name and the expanded heading */
  title: string;
  /** Cover image URL */
  src: string;
  /** Short line under the title on the tile */
  subtitle?: string;
  /** Rich content shown once the tile is expanded */
  content: React.ReactNode;
  /** Grid placement for the tile, e.g. "md:col-span-2" */
  className?: string;
}

interface Tab {
  title: React.ReactNode;
  value: string;
  content: React.ReactNode;
}

interface NavItem {
  label: string;
  href: string;
}

interface LoaderStep {
  /** What is happening during this step */
  text: string;
}

interface Testimonial {
  quote: string;
  name: string;
  role: string;
  /** Optional image URL; falls back to the person's initials */
  src?: string;
}

interface HeroParallaxProduct {
  /** Caption on the card; also the link's accessible name */
  title: string;
  /** Image URL, shown with empty alt text since the title labels it */
  image: string;
  /** Turns the card into a link */
  href?: string;
}

interface StickyScrollItem {
  title: string;
  description: string;
  /** Rendered in the pinned panel while this item is active */
  content?: React.ReactNode;
}

interface TimelineItem {
  /** Label pinned beside the entry, e.g. a date or version */
  title: React.ReactNode;
  /** Body shown to the right of the label */
  content: React.ReactNode;
}

interface SliderImage {
  /** Image URL */
  src: string;
  /** Alternative text ("" when the image is purely decorative) */
  alt: string;
}

interface GlobeMarker {
  /** Latitude in degrees */
  lat: number;
  /** Longitude in degrees */
  lng: number;
  /** Name drawn beside the marker and included in the accessible name */
  label?: string;
}

interface GlobeArc {
  /** Start as [lat, lng] */
  from: [number, number];
  /** End as [lat, lng] */
  to: [number, number];
}

interface WorldMapMarker {
  /** Latitude in degrees */
  lat: number;
  /** Longitude in degrees */
  lng: number;
  /** Text shown in a pill above the marker and used in the accessible name */
  label?: string;
  /** Ring that pulses outward from this marker */
  pulse?: boolean;
}

interface WorldMapArc {
  /** Start as [lat, lng] */
  from: [number, number];
  /** End as [lat, lng] */
  to: [number, number];
}

interface CodeFile {
  name: string;
  code: string;
  language?: string;
  highlightLines?: number[];
}
